def run(args, timeout=1.5):
    master, slave = pty.openpty(); fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH',24,80,0,0))
    env=os.environ.copy(); env['TERM']='xterm'
    p=subprocess.Popen(['./executable']+args, stdin=slave, stdout=slave, stderr=slave, env=env, close_fds=True)
    os.close(slave); out=b''; start=time.time(); sent=False
    while time.time()-start<timeout:
        if not sent and time.time()-start>0.3:
            try: os.write(master,b'\x03')
            except OSError: pass
            sent=True
        r,_,_=select.select([master],[],[],0.05)
        if r:
            try:
                c=os.read(master,4096)
                if not c: break
                out+=c
            except OSError: break
        if p.poll() is not None: break
    if p.poll() is None:
        p.terminate();
        try: p.wait(timeout=.3)
        except: p.kill(); p.wait()
    try: os.close(master)
    except: pass
    idx=out.rfind(b'\x1b[?1049l')
    return p.returncode, out[idx+8:] if idx!=-1 else out[-300:]

