CONFIG_REFERENCE = r'''
#  ____  _
# |  _ \(_)_ __  _ __       .________.
# | |_) | | '_ \| '__|      |________|
# |  __/| | |_) | |          |_    -|
# |_|   |_| .__/|_|     xX  xXx___x_|
#         |_|
#
# A commandline utility by
# Leon Kowarschick

# finish_hook: Executed once you close pipr, getting the command you constructed piped into stdin.
# finish_hook = "xclip -selection clipboard -in"

# Paranoid history mode writes every sucessfully running command into the history in autoeval mode.
paranoid_history_mode_default = false

autoeval_mode_default = true

history_size = 500
cmdlist_always_show_preview = false
cmd_timeout_millis = 2000

highlighting_enabled = true

eval_environment = ["bash", "-c"]

# Snippets can be used to quickly insert common bits of shell
# use || (two pipes) where you want your cursor to be after insertion
[snippets]
s = " | sed -r 's/||//g'"

[help_viewers]
'm' = "man ??"
'h' = "?? --help | less"

[output_viewers]
'l' = "less"
'''

BWRAP_MISSING = "bubblewrap installation not found. Please make sure you have `bwrap` on your path, or supply --no-isolation to disable safe-mode"
NON_TTY_ERR = "Error: No such device or address (os error 6)"

@dataclass
class Options:
    default: str = ""
    out_file: str | None = None
    in_file: str | None = None
    config_reference: bool = False
    raw_mode: bool = False
    no_isolation: bool = False
    help: bool = False

@dataclass
class Config:
    paranoid_history_mode_default: bool = False
    autoeval_mode_default: bool = True
    history_size: int = 500
    cmdlist_always_show_preview: bool = False
    cmd_timeout_millis: int = 2000
    highlighting_enabled: bool = True
    eval_environment: list = field(default_factory=lambda: ["bash", "-c"])
    snippets: dict = field(default_factory=lambda: {"s": " | sed -r 's/||//g'"})
    help_viewers: dict = field(default_factory=lambda: {"m": "man ??", "h": "?? --help | less"})
    output_viewers: dict = field(default_factory=lambda: {"l": "less"})
    finish_hook: str | None = None


def parse_args(argv):
    prog = argv[0]
    opts = Options()
    free = []
    i = 1
    stop = False
    while i < len(argv):
        arg = argv[i]
        if stop or arg == '-' or not arg.startswith('-'):
            free.append(arg); i += 1; continue
        if arg == '--':
            stop = True; i += 1; continue
        if arg.startswith('--'):
            body = arg[2:]
            val = None
            if '=' in body:
                name, val = body.split('=', 1)
            else:
                name = body
            need = {"default", "out-file", "in-file"}
            flags = {"config-reference", "raw-mode", "no-isolation", "help"}
            if name in need:
                if val is None:
                    if i + 1 >= len(argv):
                        return None, f"Argument to option '{name}' missing"
                    val = argv[i+1]; i += 1
                if name == 'default': opts.default = val
                elif name == 'out-file': opts.out_file = val
                elif name == 'in-file': opts.in_file = val
            elif name in flags:
                if val is not None:
                    return None, f"Option '{name}' does not take an argument"
                if name == 'config-reference': opts.config_reference = True
                elif name == 'raw-mode': opts.raw_mode = True
                elif name == 'no-isolation': opts.no_isolation = True
                elif name == 'help': opts.help = True
            else:
                return None, f"Unrecognized option: '{name}'"
            i += 1; continue
        # short options, getopts-like grouping
        s = arg[1:]
        j = 0
        while j < len(s):
            ch = s[j]
            if ch in ('d', 'o'):
                val = s[j+1:]
                if val == "":
                    if i + 1 >= len(argv):
                        return None, f"Argument to option '{ch}' missing"
                    val = argv[i+1]; i += 1
                if ch == 'd': opts.default = val
                else: opts.out_file = val
                j = len(s)
            elif ch == 'r':
                opts.raw_mode = True; j += 1
            elif ch == 'h':
                opts.help = True; j += 1
            else:
                return None, f"Unrecognized option: '{ch}'"
        i += 1
    return opts, None


def config_dir():
    return os.path.join(os.path.expanduser('~'), '.config', 'pipr')

def config_path(): return os.path.join(config_dir(), 'pipr.toml')
def history_path(): return os.path.join(config_dir(), 'history')
def bookmarks_path(): return os.path.join(config_dir(), 'bookmarks')


def ensure_default_config():
    d = config_dir()
    os.makedirs(d, exist_ok=True)
    p = config_path()
    if not os.path.exists(p):
        with open(p, 'w', encoding='utf-8') as f:
            f.write(CONFIG_REFERENCE)


def load_config():
    ensure_default_config()
    cfg = Config()
    p = config_path()
    try:
        try:
            import tomllib
            with open(p, 'rb') as f:
                data = tomllib.load(f)
        except ModuleNotFoundError:
            data = parse_toml_loose(open(p, encoding='utf-8').read())
    except Exception as e:
        # The original binary panics on malformed TOML. Reproduce the user-visible spirit.
        sys.stderr.write(f"panicked at configuration parsing: {e} in {p}\n")
        sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
        sys.exit(101)
    if isinstance(data, dict):
        for k in ['paranoid_history_mode_default','autoeval_mode_default','cmdlist_always_show_preview','highlighting_enabled']:
            if k in data: setattr(cfg, k, bool(data[k]))
        for k in ['history_size','cmd_timeout_millis']:
            if k in data:
                try: setattr(cfg, k, int(data[k]))
                except Exception: pass
        if isinstance(data.get('eval_environment'), list) and data['eval_environment']:
            cfg.eval_environment = [str(x) for x in data['eval_environment']]
        if isinstance(data.get('snippets'), dict):
            cfg.snippets = {str(k): str(v) for k,v in data['snippets'].items()}
        if isinstance(data.get('help_viewers'), dict):
            cfg.help_viewers = {str(k): str(v) for k,v in data['help_viewers'].items()}
        if isinstance(data.get('output_viewers'), dict):
            cfg.output_viewers = {str(k): str(v) for k,v in data['output_viewers'].items()}
        if 'finish_hook' in data:
            cfg.finish_hook = str(data['finish_hook'])
    return cfg


def parse_toml_loose(text):
    # Tiny fallback parser for the simple default file.
    res = {}; section = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'): continue
        if line.startswith('[') and line.endswith(']'):
            section = line[1:-1].strip(); res.setdefault(section, {}); continue
        if '=' not in line: continue
        k,v = line.split('=',1); k=k.strip().strip('"\''); v=v.strip()
        if '#' in v and not (v.startswith('"') or v.startswith("'")):
            v = v.split('#',1)[0].strip()
        if v.lower() in ('true','false'): val = v.lower() == 'true'
        elif v.startswith('[') and v.endswith(']'):
            val = [x.strip().strip('"\'') for x in v[1:-1].split(',') if x.strip()]
        elif (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
            val = v[1:-1]
        else:
            try: val = int(v)
            except Exception: val = v
        if section: res.setdefault(section,{})[k]=val
        else: res[k]=val
    return res


def read_list_file(path):
    try:
        data = open(path, 'r', encoding='utf-8').read()
    except FileNotFoundError:
        return []
    if data == '': return []
    return data.split('\n---\n')


def write_list_file(path, items):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        f.write('\n---\n'.join(items))


def display_command(cmd, raw=False):
    if raw:
        return cmd
    return ' '.join(cmd.splitlines())


def executable_command(cmd):
    lines = []
    for line in cmd.splitlines() or [cmd]:
        if line.lstrip().startswith('#'):
            continue
        lines.append(line)
    return '\n'.join(lines).strip('\n')


def run_command(cmd, cfg):
    ecmd = executable_command(cmd)
    if ecmd.strip() == '':
        return b'', b'', None
    envcmd = list(cfg.eval_environment or ['bash','-c'])
    full = envcmd + [ecmd]
    try:
        p = subprocess.run(full, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                           timeout=max(0.001, cfg.cmd_timeout_millis/1000.0))
        return p.stdout, p.stderr, p.returncode
    except subprocess.TimeoutExpired:
        return b'', f"command timed out after {cfg.cmd_timeout_millis}ms".encode(), None
    except Exception as e:
        return b'', (str(e) + '\n').encode(), None


def strip_for_width(s, w):
    # crude printable-width trimming; adequate for ASCII command/output.
    return s[:max(0,w)]


def move(y,x): return f"\x1b[{y};{x}H"

def ansi_clear(): return "\x1b[2J"

def draw_box(lines, title, x, y, w, h, title_colored=True, footer=None):
    if w < 2 or h < 2: return ''
    out=[]
    title_text = f" {title} " if title else ''
    visible_title = title_text
    rem = max(0, w - 2 - len(visible_title))
    if footer and h >= 2:
        footer_text = footer
    else:
        footer_text = None
    top = '┌'
    if visible_title:
        if title_colored:
            top += "\x1b[38;5;0;48;5;6m" + visible_title + "\x1b[39;49m"
        else:
            top += visible_title
    top += '─' * rem + '┐'
    out.append(move(y,x)+top)
    inner_w = w-2
    for i in range(h-2):
        content = ''
        if i < len(lines):
            try: content = lines[i].decode('utf-8','replace') if isinstance(lines[i], bytes) else str(lines[i])
            except Exception: content = str(lines[i])
        content = content.replace('\t','    ').replace('\r','')
        content = strip_for_width(content, inner_w)
        out.append(move(y+1+i,x)+'│'+content+' '*(inner_w-len(content))+'│')
    if footer_text and len(footer_text)+2 < w:
        dash_count = w - 2 - len(footer_text)
        bottom = '└' + '─'*dash_count + footer_text + '──┘'
        # compensate: the suffix has two extra dashes before corner as ratatui-looking decoration
        if len(bottom) > w: bottom = bottom[:w-1] + '┘'
        elif len(bottom) < w: bottom = bottom[:-1] + '─'*(w-len(bottom)) + '┘'
    else:
        bottom = '└' + '─'*(w-2) + '┘'
    out.append(move(y+h-1,x)+bottom)
    return ''.join(out)


class App:
    def __init__(self, opts, cfg, initial):
        self.opts=opts; self.cfg=cfg; self.cmd=initial; self.cursor=len(initial)
        self.autoeval=cfg.autoeval_mode_default
        self.paranoid=cfg.paranoid_history_mode_default
        self.stdout=b''; self.stderr=b''; self.returncode=None
        self.history=read_list_file(history_path()); self.hist_index=None
        self.bookmarks=read_list_file(bookmarks_path())
        self.show_help=False; self.show_history=False; self.show_bookmarks=False; self.snippet_mode=False
        if self.cmd.strip(): self.evaluate()
    def evaluate(self):
        self.stdout,self.stderr,self.returncode = run_command(self.cmd,self.cfg)
        if self.paranoid and self.returncode == 0 and self.cmd.strip():
            self.add_history(self.cmd)
    def add_history(self, cmd):
        if not cmd: return
        self.history.append(cmd)
        if self.cfg.history_size > 0 and len(self.history) > self.cfg.history_size:
            self.history = self.history[-self.cfg.history_size:]
        write_list_file(history_path(), self.history)
    def save_bookmark(self):
        if self.cmd and self.cmd not in self.bookmarks:
            self.bookmarks.append(self.cmd); write_list_file(bookmarks_path(), self.bookmarks)
    def insert(self, s):
        self.cmd = self.cmd[:self.cursor] + s + self.cmd[self.cursor:]
        self.cursor += len(s)
        if self.autoeval: self.evaluate()
    def delete_back(self):
        if self.cursor>0:
            self.cmd = self.cmd[:self.cursor-1]+self.cmd[self.cursor:]; self.cursor-=1
            if self.autoeval: self.evaluate()
    def set_cmd(self, s):
        self.cmd=s; self.cursor=len(s)
        if self.autoeval: self.evaluate()
    def history_prev(self):
        if not self.history: return
        if self.hist_index is None: self.hist_index=len(self.history)-1
        else: self.hist_index=max(0,self.hist_index-1)
        self.set_cmd(self.history[self.hist_index])
    def history_next(self):
        if not self.history: return
        if self.hist_index is None: return
        self.hist_index += 1
        if self.hist_index >= len(self.history): self.hist_index=None; self.set_cmd('')
        else: self.set_cmd(self.history[self.hist_index])
    def choose_from_list(self, items):
        if items: self.set_cmd(items[-1])
    def draw(self):
        cols, rows = shutil.get_terminal_size((80,24))
        cols=max(cols,20); rows=max(rows,8)
        x=2; y=2; w=max(10, cols-2)
        cmd_lines=self.cmd.split('\n') if self.cmd!='' else ['']
        cmd_h=max(3,min(max(3,len(cmd_lines)+2), max(3, rows//3)))
        title='Command' + (' [Autoeval]' if self.autoeval else '') + (' [Paranoid]' if self.paranoid else '')
        out=[ansi_clear()]
        out.append(draw_box(cmd_lines[:cmd_h-2], title, x,y,w,cmd_h, True))
        rest_y=y+cmd_h; rest_h=rows-rest_y
        if rest_h < 3: rest_h=3
        stdout_lines=self.stdout.decode('utf-8','replace').splitlines()
        stderr_lines=self.stderr.decode('utf-8','replace').splitlines()
        out_title='Output' + (' [+]' if self.cmd.strip() else '')
        if stderr_lines:
            oh=max(3,(rest_h+1)//2); sh=max(3,rest_h-oh+1)
            out.append(draw_box(stdout_lines[:oh-2], out_title, x, rest_y, w, oh, True))
            out.append(draw_box(stderr_lines[:sh-2], 'Stderr', x, rest_y+oh, w, sh, True, footer='Help:F1'))
        else:
            out.append(draw_box(stdout_lines[:rest_h-2], out_title, x, rest_y, w, rest_h, True, footer='Help:F1'))
        if self.show_help:
            out.append(self.draw_help(cols, rows))
        elif self.show_history:
            out.append(self.draw_list('History', self.history, cols, rows))
        elif self.show_bookmarks:
            out.append(self.draw_list('Bookmarks', self.bookmarks, cols, rows))
        elif self.snippet_mode:
            items=[f"{k}: {v}" for k,v in sorted(self.cfg.snippets.items())]
            out.append(self.draw_list('Snippets', items, cols, rows))
        # cursor position in command box
        before=self.cmd[:self.cursor]
        cy=before.count('\n')
        cx=len(before.rsplit('\n',1)[-1])
        cy=min(cy, cmd_h-3); cx=min(cx, w-3)
        out.append('\x1b[39m\x1b[49m\x1b[0m\x1b[?25h')
        out.append(move(y+1+cy, x+1+cx))
        return ''.join(out)
    def draw_help(self, cols, rows):
        lines=[
            ('F1', 'Show/hide help'),
            ('F2', 'Toggle autoeval'),
            ('F3', 'Toggle Paranoid history (fills up history in autoeval)'),
            ('F4', 'Show/hide history'),
            ('Ctrl+B', 'Show/hide bookmarks'),
            ('F5', 'Open help viewer'),
            ('F6', 'Open output viewer'),
            ('F7', 'When the cursor is on a `|` symbol, cache the output of everything before that |'),
            ('Ctrl+S', 'Save bookmark'),
            ('Alt+Return', 'Newline'),
            ('Ctrl+U', 'Clear Command'),
            ('Ctrl+P', 'Previous in history'),
            ('Ctrl+N', 'Next in history'),
            ('Ctrl+V', 'Insert snippet (press corresponding key to choose)'),
            ('', 'disable a line by starting it with a #'),
            ('', 'this will simply exclude the line from the executed command.'),
            ('', 'Config file is in ~/.config/pipr/pipr.toml'),
        ]
        rendered=[]
        for k,v in lines:
            rendered.append((k.ljust(12)+v) if k else v)
        ww=min(cols-4, 94); hh=min(rows-4, len(rendered)+2)
        return draw_box(rendered[:hh-2], 'Help', 3, 3, ww, hh, False)
    def draw_list(self, title, items, cols, rows):
        rendered=[str(x).replace('\n',' ') for x in (items[-(rows-6):] if items else [''])]
        ww=min(cols-4, 94); hh=min(rows-4, max(3,len(rendered)+2))
        return draw_box(rendered[:hh-2], title, 3,3,ww,hh,False)
    def handle_seq(self, seq):
        # returns True to exit
        if self.snippet_mode and len(seq)==1 and seq.decode('latin1','ignore') in self.cfg.snippets:
            snip=self.cfg.snippets[seq.decode('latin1')]
            pos=snip.find('||')
            if pos>=0:
                snip2=snip.replace('||','',1); self.insert(snip2); self.cursor = self.cursor - (len(snip2)-pos)
            else: self.insert(snip)
            self.snippet_mode=False; return False
        if seq in (b'\x03', b'\x11'): return True
        if seq == b'\x1b': return True
        if seq in (b'\r', b'\n'):
            self.evaluate(); self.add_history(self.cmd) if self.cmd else None; return False
        if seq in (b'\x7f', b'\x08'):
            self.delete_back(); return False
        if seq == b'\x15':
            self.set_cmd(''); return False
        if seq == b'\x10': self.history_prev(); return False
        if seq == b'\x0e': self.history_next(); return False
        if seq == b'\x13': self.save_bookmark(); return False
        if seq == b'\x02': self.show_bookmarks=not self.show_bookmarks; self.show_help=self.show_history=False; return False
        if seq == b'\x16': self.snippet_mode=not self.snippet_mode; self.show_help=self.show_history=self.show_bookmarks=False; return False
        if seq in (b'\x1bOP', b'\x1b[11~'): self.show_help=not self.show_help; self.show_history=self.show_bookmarks=self.snippet_mode=False; return False
        if seq in (b'\x1bOQ', b'\x1b[12~'): self.autoeval=not self.autoeval; return False
        if seq in (b'\x1bOR', b'\x1b[13~'): self.paranoid=not self.paranoid; return False
        if seq in (b'\x1bOS', b'\x1b[14~'): self.show_history=not self.show_history; self.show_help=self.show_bookmarks=self.snippet_mode=False; return False
        if seq in (b'\x1b[15~',): return False
        if seq in (b'\x1b[17~',): return False
        if seq in (b'\x1b[18~',): return False
        if seq in (b'\x1b\r', b'\x1b\n'):
            self.insert('\n'); return False
        if seq == b'\x1b[D': self.cursor=max(0,self.cursor-1); return False
        if seq == b'\x1b[C': self.cursor=min(len(self.cmd),self.cursor+1); return False
        if seq == b'\x1b[A': self.history_prev(); return False
        if seq == b'\x1b[B': self.history_next(); return False
        if seq.startswith(b'\x1b'):
            return False
        try:
            text=seq.decode('utf-8')
        except Exception:
            text=''
        for ch in text:
            if ch.isprintable() or ch == '\t': self.insert(ch)
        return False


def read_key(fd):
    b=os.read(fd,1)
    if not b: return b
    if b == b'\x1b':
        # collect immediate escape-sequence bytes, but let lone ESC mean exit.
        seq=b
        end=time.time()+0.05
        while time.time()<end:
            r,_,_=select.select([fd],[],[], max(0,end-time.time()))
            if not r: break
            c=os.read(fd,1); seq+=c
            if (seq.startswith(b'\x1b[') and (c.isalpha() or c==b'~')) or (seq.startswith(b'\x1bO') and len(seq)>=3) or seq in (b'\x1b\r',b'\x1b\n'):
                break
        return seq
    # consume rest of a UTF-8 printable if available? Raw ASCII is enough; bytes of UTF-8 will pass one by one.
    return b


def run_tui(opts, cfg, initial):
    if not (sys.stdin.isatty() and sys.stdout.isatty()):
        sys.stderr.write('\x1b[?1049h' + NON_TTY_ERR + '\n')
        return 1
    app=App(opts,cfg,initial)
    fd=sys.stdin.fileno()
    old=termios.tcgetattr(fd)
    final=''
    try:
        tty.setraw(fd)
        sys.stdout.write('\x1b[?1049h')
        sys.stdout.write(app.draw()); sys.stdout.flush()
        while True:
            r,_,_=select.select([fd],[],[],0.2)
            if r:
                seq=read_key(fd)
                if app.handle_seq(seq):
                    break
                sys.stdout.write(app.draw()); sys.stdout.flush()
            else:
                # keep the cursor visible, like the original's periodic ticks
                sys.stdout.write('\x1b[?25h'); sys.stdout.flush()
        final=display_command(app.cmd, opts.raw_mode)
        if app.cmd:
            app.add_history(app.cmd)
    finally:
        sys.stdout.write('\x1b[?1049l')
        sys.stdout.flush()
        try: termios.tcsetattr(fd, termios.TCSADRAIN, old)
        except Exception: pass
    if opts.out_file:
        try:
            with open(opts.out_file,'w',encoding='utf-8') as f: f.write(final)
        except Exception as e:
            sys.stderr.write(f"Error: {e}\n")
            return 1
    if cfg.finish_hook:
        try:
            subprocess.run(cfg.finish_hook, input=final.encode(), shell=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            pass
    sys.stdout.write(final + '\n')
    sys.stdout.flush()
    return 0


def main(argv):
    opts, err = parse_args(argv)
    prog=argv[0]
    if err:
        sys.stderr.write(f"{prog}: {err}\n")
        return 1
    if opts.help:
        sys.stdout.write(HELP_TEXT.format(prog=prog))
        return 0
    if opts.config_reference:
        sys.stdout.write(CONFIG_REFERENCE)
        return 0
    if not opts.no_isolation and shutil.which('bwrap') is None:
        sys.stdout.write(BWRAP_MISSING + '\n')
        return 1
    cfg=load_config()
    initial=opts.default
    if opts.in_file:
        try:
            with open(opts.in_file,'r',encoding='utf-8') as f: initial=f.read()
        except Exception as e:
            sys.stderr.write(f"Error: {e}\n")
            return 1
    return run_tui(opts,cfg,initial)

if __name__ == '__main__':
    try:
        raise SystemExit(main(sys.argv))
    except KeyboardInterrupt:
        raise SystemExit(130)
